// Keep the conversation above the touch navigation, even when header content wraps.
const header=document.querySelector('.topbar'),layout=document.querySelector('.app-layout');
if(header&&layout){
 const actions=header.querySelector('.top-actions'),exportButton=document.querySelector('#export-open'),secondary=[...header.querySelectorAll('.editor-account,#new-project,#history-open,#settings-open')],more=document.createElement('button'),menu=document.createElement('dialog');
 more.type='button';more.className='editor-more-toggle';more.textContent='Ещё';more.setAttribute('aria-label','Другие действия с проектом');more.setAttribute('aria-haspopup','dialog');more.setAttribute('aria-expanded','false');menu.id='editor-more-menu';menu.className='editor-more-menu';menu.setAttribute('aria-label','Действия с проектом');more.setAttribute('aria-controls',menu.id);
 const menuHeading=document.createElement('div');menuHeading.className='dialog-heading';const title=document.createElement('h2');title.textContent='Действия с проектом';const close=document.createElement('button');close.className='dialog-close';close.type='button';close.textContent='×';close.setAttribute('aria-label','Закрыть действия');close.addEventListener('click',()=>menu.close());menuHeading.append(title,close);const menuActions=document.createElement('div');menuActions.className='editor-more-actions';menu.append(menuHeading,menuActions);document.body.append(menu);actions.insertBefore(more,exportButton);
 more.addEventListener('click',()=>{menu.showModal();more.setAttribute('aria-expanded','true')});menu.addEventListener('close',()=>more.setAttribute('aria-expanded','false'));secondary.forEach(button=>button.addEventListener('click',()=>{if(menu.open)menu.close()}));
 const compact=matchMedia('(max-width:1023px)'),applyCompact=()=>{if(menu.open)menu.close();if(compact.matches){secondary.forEach(button=>menuActions.append(button));more.hidden=false}else{secondary.forEach(button=>actions.insertBefore(button,exportButton));more.hidden=true}};compact.addEventListener('change',applyCompact);applyCompact();
 const update=()=>{document.documentElement.style.setProperty('--editor-header-height',Math.ceil(layout.getBoundingClientRect().top+scrollY)+'px');const viewport=window.visualViewport;document.documentElement.style.setProperty('--editor-viewport-height',(viewport?.height||innerHeight)+'px');document.body.classList.toggle('editor-keyboard-open',!!viewport&&viewport.height<innerHeight*.75)};
 const observer=new ResizeObserver(update);observer.observe(header);const notice=document.querySelector('.subscription-notice');if(notice)observer.observe(notice);window.addEventListener('resize',update);window.visualViewport?.addEventListener('resize',update);document.fonts.ready.then(update);update();
 const positions=new Map();document.querySelectorAll('[data-mobile]').forEach(button=>{button.setAttribute('aria-pressed',String(button.dataset.mobile==='edit'));const panel=document.querySelector(button.dataset.mobile==='media'?'.media-panel':button.dataset.mobile==='chat'?'.chat-panel':'.edit-panel');if(panel){panel.id='mobile-panel-'+button.dataset.mobile;button.setAttribute('aria-controls',panel.id)}button.addEventListener('click',()=>{const previous=document.querySelector('[data-mobile][aria-pressed=true]')?.dataset.mobile;positions.set(previous,scrollY);if(matchMedia('(max-width:1023px)').matches)requestAnimationFrame(()=>{window.scrollTo({top:positions.get(button.dataset.mobile)||0,behavior:'instant'});update()})})});
}
